(function(){'use strict';const label=document.createElement('label');label.className='format-control';label.innerHTML='Format <select id="projectFormat" aria-label="Video format"><option value="16:9">16:9 Landscape</option><option value="9:16">9:16 Portrait</option></select>';$('.workspace-controls').append(label);
function sync(){const portrait=project.format==='9:16';M.W=portrait?607.5:1920;M.H=1080;for(const f of project.frames)f.format=portrait?'9:16':'16:9';stage.style.aspectRatio=portrait?'9 / 16':'16 / 9';$('#projectFormat').value=portrait?'9:16':'16:9';window.WorkspaceView?.resize()}
$('#projectFormat').onchange=()=>{stop();remember();project.format=$('#projectFormat').value;window.PreviewPerformance?.invalidateAll();sync();changed();toast(project.format==='9:16'?'Portrait format. Reframe existing scenes using Camera controls.':'Landscape format selected.')};const refresh=refreshUI;refreshUI=function(){sync();refresh()};sync();refreshUI();})();
